INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(64, 'Bihar School Teacher Recruitment 2024  Admit Card', 'Bihar Public Service Commission (BPSC) School Teacher TRE 3.0 Recruitment 2024', '<table style=\"border-collapse: collapse; width: 100%; border-spacing: 0px; margin-left: auto; margin-right: auto; border: 3px dashed rgb(185, 106, 217);\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"4\" valign=\"top\">\r\n<h2 align=\"center\"><span style=\"color: rgb(35, 111, 161); font-size: 14pt; font-family: \'arial black\', sans-serif;\"><strong>👨&zwj;🎓&nbsp; Bihar Public Service Commission (BPSC)</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(241, 196, 15); font-size: 14pt; font-family: \'arial black\', sans-serif;\"><strong>BPSC&nbsp;Bihar School Teacher TRE 3.0 Recruitment 2024</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(185, 106, 217); font-size: 14pt; font-family: \'arial black\', sans-serif;\"><strong>Bihar Teacher Bharti TRE 3 Advt No. 22/2024:&nbsp; Short Details of Notification</strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"3\" valign=\"top\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: \'book antiqua\', palatino, serif; text-decoration: underline;\"><strong>📌&nbsp; Important Dates&nbsp;</strong></span></span></em></h2>\r\n<ol>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Application Begin : <strong>10/02/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Last Date for Apply Online : <span style=\"color: #ff0000;\"><strong>26/02/2024</strong></span></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Pay Exam Fee Last Date : <strong>26/02/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Exam Date :<strong>15 March 2024 </strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Exam Date :<strong>16 March 2024 (Postponed) </strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Admit Card Available :<strong>07 March 2024 </strong></span></li>\r\n</ol>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: \'book antiqua\', palatino, serif; text-decoration: underline;\"><strong>📌&nbsp; Application Fee</strong></span></span></em></h2>\r\n<ol>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">General / OBC/ Other State : <strong>750/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">SC / ST / PH : <strong>200/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Female Candidate (Bihar Dom.) : <strong>200/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Pay the Exam Fee Through Online / Offline Fee Mode Only</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"4\" valign=\"top\">\r\n<h2 align=\"center\"><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: \'book antiqua\', palatino, serif; text-decoration: underline;\"><strong>BPSC&nbsp;School Teacher TRE 3.0 Recruitment 2024 : </strong><span style=\"color: red; text-decoration: underline;\"><strong>Age Limit as on 01/08/2023 </strong></span></span></span></h2>\r\n<ol>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Minimum Age : <strong>18 Years for Primary Teacher</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Minimum Age :<strong> 21 Years for TGT / PGT Teacher</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Maximum Age : <strong>37 Years for Male &amp; 40 Years for Female </strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Read the Notification for Age Relaxation in BPSC School Primary, TGT, PGT Teacher Recruitment 2024.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"4\" valign=\"top\">\r\n<h2 align=\"center\"><span style=\"text-decoration: underline;\"><span style=\"color: red; font-size: 12pt; font-family: \'book antiqua\', palatino, serif; text-decoration: underline;\"><strong>Bihar School Teacher TRE 3 Exam 2024&nbsp; : </strong><span style=\"color: rgb(0, 128, 0); text-decoration: underline;\"><strong>Vacancy Details Total : 86391 Post </strong></span></span></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\"><strong>Post Name</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\"><strong>Total Post</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\"><strong>Bihar School Teacher Eligibility TRE 3.0 </strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Primary School Teacher Class 1-5</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">28026</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<ol>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Senior Secondary with 50% Marks and 2 Year Diploma in Elementary Education <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Senior Secondary with 45% Marks and 2 Year Diploma in Elementary Education (AS PER NCTE Norms 2002) <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Senior Secondary with 50% Marks and 4 Year B.L.Ed Course <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Senior Secondary with 50% Marks and 2 Year Diploma in Elementary Education (Special) <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bachelor Degree in Any Stream with 2 Year Diploma in Elementary Education</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\"><strong>CTET / BTET Paper I Exam Passed</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">More Eligibility Read the Notification.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Middle School Teacher Class 6-8</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">19057</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<ol>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bachelor Degree with 2 Year Diploma in Elementary Education <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bachelor / Master Degree with 50% Marks with B.Ed <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bachelor Degree with 45% Marks and B.Ed (NCTE Norms) <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bachelor Degree with 50% Marks and BA BED and B.Sc Ed&nbsp; <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bachelor Degree with 50% Marks and B.Ed Special <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Master Degree with 55% Marks and 3 Year B.Ed - M.Ed Course.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\"><strong>CTET / BTET Paper II Exam Passed</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">More Eligibility Read the Notification.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">TGT Teacher Class 9-10</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">16870</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<ol>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bachelor / Master Degree in Related Subject with Minimum 50% Marks and B.Ed Degree <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bachelor / Master Degree in Related Subject with Minimum 45% Marks (As per 2002 Norms) &nbsp;and B.Ed Degree <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">4 Year Degree in BAEd / BScEd</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">STET Paper I Exam Passed</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">More Eligibility Read the Notification.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">TGT Teacher Class 9-10 (Special)</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">65</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<ol>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bachelor / Master Degree in Related Subject with Minimum 50% Marks and B.Ed Degree <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bachelor / Master Degree in Related Subject with Minimum 45% Marks (As per 2002 Norms) &nbsp;and B.Ed Degree <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">4 Year Degree in BAEd / BScEd</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">STET Paper I Exam Passed</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">More Eligibility Read the Notification.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">PGT Teacher Class 11-12</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">22373</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<ol>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Master Degree in Related Subject with Minimum 50% Marks and B.Ed Degree <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Master Degree in Related Subject with Minimum 45% Marks (As per 2002 Norms) &nbsp;and B.Ed Degree <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Master Degree in Related Subject with 4 Year Degree in BAEd / BScEd <strong>OR</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Master Degree with 55% Marks and B.Ed &ndash; Med 3 Year Degree.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">STET Paper II Exam Passed</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">More Eligibility Read the Notification.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"4\" valign=\"top\">\r\n<h2 align=\"center\"><span style=\"text-decoration: underline;\"><span style=\"color: red; font-size: 12pt; font-family: \'book antiqua\', palatino, serif; text-decoration: underline;\"><strong>Important Information : <span style=\"color: rgb(0, 128, 0); text-decoration: underline;\">Before Filling BPSC TRE 3.0 Form</span></strong></span></span></h2>\r\n<ol>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bihar STET / CTET Appearing Candidate Are Not Eligible to Fill Form.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">While applying, BSEB Unique ID number has to be written in place of Bihar STET 2023 Result Card Number.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Central Teacher Eligibility Test CTET candidates will fill the serial number mentioned in the certificate/mark sheet in the form.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Do Not Need to Send Application Form to BPSC.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">More Details Must Read the BPSC TRE 3.0 Notification.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"4\" valign=\"top\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: \'book antiqua\', palatino, serif; text-decoration: underline;\"><strong>🔎&nbsp; How to Fill BPSC School Teacher : Online Form 2024</strong></span></span></em></h2>\r\n<ol>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Bihar Public Service Commission BPSC Are Issued Primary Teacher, Trained Graduate Teacher TGT &amp; Post Graduate Teacher PGT Recruitment Notification 2024 and Invited Online Application Form for the BPSC School Teacher Exam 2024 TRE III Candidate Can Apply Online for <strong>10/02/2024 to 26/02/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Candidate Read the Notification Before Apply the BPSC Latest School Teacher Phase III (Third) Recruitment 2024 Application Form in Sarkari Result Recruitment Latest Job Section.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Kindly Check and Collect the All Document - Hand Writing, Eligibility, ID Proof, Address Details, Basic Details.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Kindly Ready Scan Document Related to Recruitment Form - Photo, Sign, ID, Thumb, Proof, Etc.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Before Submit the Application Form Must Check the Preview and All Column Carefully.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">If Candidate Required to Paying the Application Fee Must Submit. If You have Not the Required Application Fees Your Form is Not Completed.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\">Take A Print Out of Final Submitted Form.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"4\" valign=\"top\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: \'book antiqua\', palatino, serif; text-decoration: underline;\"><strong>🔗&nbsp; Some Useful Important Links</strong></span></span></em></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<h2 style=\"text-align: left; padding-left: 40px;\" align=\"center\"><span style=\"color: red; font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\"><strong>Download Admit Card</strong></span></h2>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<h2 align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\"><strong><a title=\"BPSC School Teacher Admit Card 2024\" href=\"https://onlinebpsc.bihar.gov.in/main/home\" target=\"_blank\" rel=\"noopener\">Click Here</a></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<h2 style=\"text-align: left; padding-left: 40px;\" align=\"center\"><span style=\"color: red; font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\"><strong>How to Download Admit Card (Video Hindi)</strong></span></h2>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<h2 align=\"center\"><span style=\"font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\"><strong><a title=\"BPSC School Teacher Admit Card 2024\" href=\"https://www.youtube.com/watch?v=9b1_o9oHiLc\" target=\"_blank\" rel=\"noopener\">Click Here</a></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(185, 106, 217);\" colspan=\"2\" valign=\"top\">\r\n<h2 style=\"text-align: left; padding-left: 40px;\" align=\"center\"><span style=\"color: red; font-size: 12pt; font-family: \'book antiqua\', palatino, serif;\"><strong>Download 16 March 2024 Exam Postponed Noti