INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(81, 'Railway Recruitment Board RRB Technician CEN 022024 Apply Online for 9144 Post', 'Indian Railway (Railway Recruitment Board) has relased Technician Recruitment 2024. Those candidates who are interested in this RRB Prayagraj, RRB Gorakhpur, RRB Ajmer, RRB Kolkata, RRB Mumbai, RRB Secunderabad, RRB Chennai and Other recruitment can', '<table style=\"border-collapse: collapse; width: 100%; border-spacing: 0px; border: 1px dotted rgb(132, 63, 161);\" border=\"1\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"12\" valign=\"top\">\r\n<h4 align=\"center\"><span style=\"font-size: 14pt;\"><span style=\"color: rgb(25, 62, 185);\"><strong>👨&zwj;🎓&nbsp; Railway Recruitment Board (RRB)</strong></span><strong> </strong></span></h4>\r\n<h4 align=\"center\"><span style=\"color: rgba(24, 195, 189, 0.42); font-size: 14pt;\"><strong>Railway Technician Grade I Signal &amp; Technical Grade III Recruitment 2024</strong></span></h4>\r\n<h4 align=\"center\"><span style=\"color: rgba(225, 219, 25, 0.607); font-size: 14pt;\"><strong>RRB Technician Advt No. : CEN 02/2024 : &nbsp;Short Details of Notification</strong></span></h4>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"6\" valign=\"top\" width=\"379\">\r\n<h4 align=\"center\"><span style=\"text-decoration: underline; font-size: 12pt;\"><span style=\"color: rgb(0, 128, 0); text-decoration: underline;\"><strong>📌Important Dates</strong></span></span></h4>\r\n<ol>\r\n<li><span style=\"font-size: 12pt;\">Application Begin : <strong>09/03/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Last Date for Apply Online : <span style=\"color: #ff0000;\"><strong>08/04/2024</strong></span></span></li>\r\n<li><span style=\"font-size: 12pt;\">Last Date Pay Exam Fee : <strong>08/04/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Correction / Modified Form : <strong>09-18 April 2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Exam Date : <strong>As per Schedule </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Admit Card Available : <strong>Notified Soon&nbsp; </strong></span></li>\r\n</ol>\r\n</td>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"6\" valign=\"top\">\r\n<h4 align=\"center\"><span style=\"text-decoration: underline; font-size: 12pt;\"><span style=\"color: rgb(0, 128, 0); text-decoration: underline;\"><strong>📌Application Fee</strong></span></span></h4>\r\n<ol>\r\n<li><span style=\"font-size: 12pt;\">General / OBC / EWS : <strong>500/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">SC / ST / PH <strong>: 250/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">All Category Female <strong>: 250/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>After Appear the Stage I Exam </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">UR/OBC/EWS Fee Refund : <strong>400/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">SC / ST / PH / Female Refund <strong>: 250/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Pay the Examination Fee Through Debit Card, Credit Card, Net Banking Fee Mode Only.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"12\" valign=\"top\">\r\n<h4 align=\"center\"><span style=\"text-decoration: underline; font-size: 12pt;\"><span style=\"color: rgb(0, 128, 0); text-decoration: underline;\"><strong>Railway Technician Notification 2024 : </strong><span style=\"color: red; text-decoration: underline;\"><strong>Age Limit as on 01/07/2024</strong></span></span></span></h4>\r\n<ol>\r\n<li><span style=\"font-size: 12pt;\">Minimum Age : <strong>18 Years</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Maximum Age : <strong>33 Years for Technician Grade III</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Maximum Age :<strong> 36 Years for Technician Grade I Signal </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Age Relaxation Extra as per Railway Recruitment Board RRB Technician Recruitment Advt No. CEN 02/2024 Vacancy Rules.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"12\" valign=\"top\">\r\n<h4 align=\"center\"><span style=\"text-decoration: underline; font-size: 12pt;\"><span style=\"color: red; text-decoration: underline;\"><strong>RRB Technician Recruitment 2024 : </strong><strong>&nbsp;<span style=\"color: rgb(0, 128, 0); text-decoration: underline;\">Vacancy Details Total : 9144 Post</span></strong></span></span></h4>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"2\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\"><strong>Post Name</strong></span></p>\r\n</td>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"4\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\"><strong>Total Post</strong></span></p>\r\n</td>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"6\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\"><strong>Railway RRB Technician Eligibility 2024</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"2\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\">Technician Grade 1 Signal</span></p>\r\n</td>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"4\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\">1092</span></p>\r\n</td>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"6\" valign=\"top\">\r\n<ol>\r\n<li><span style=\"font-size: 12pt;\">Bachelor Degree of Science in Physics / Electronics / Computer Science / Information Technology / Instrumentation OR</span></li>\r\n<li><span style=\"font-size: 12pt;\">&nbsp;B.SC in a Combination&nbsp; of Any Sub Stream of Physics / Electronics / Computer Science / IT / Instrumentation OR</span></li>\r\n<li><span style=\"font-size: 12pt;\">BE / B.Tech&nbsp; / 3 Year Engineering Polytechnic Diploma in Above Basic Stream.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"2\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\">Technical Grade 3 (Blacksmith / Bridge / Carriage and Wagon / Crane Driver / Diesel Electrical / Diesel Mechanical / Electrical / Electrical / TRS / EMU / Fitter / Permanent Way / Refrigeration and AC / Riveter / S&amp;T / Track Machine / Turner / Welder /</span></p>\r\n</td>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"4\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\">8052</span></p>\r\n</td>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"6\" valign=\"top\">\r\n<ol>\r\n<li><span style=\"font-size: 12pt;\">Class 10th with ITI Certificate from NCVT / SCVT in Related Trade / Branch.</span></li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"12\" valign=\"top\">\r\n<h4 align=\"center\"><span style=\"text-decoration: underline; font-size: 12pt;\"><span style=\"color: rgb(0, 128, 0); text-decoration: underline;\"><strong>Railway RRB Technician CEN 02/2024 :<span style=\"color: red; text-decoration: underline;\"> Zone Wise Vacancy Details:&nbsp; </span></strong><span style=\"color: red; text-decoration: underline;\"><strong>Category Wise Vacancy Details</strong></span></span><strong> </strong></span></h4>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-color: rgb(132, 63, 161);\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\"><strong>RRB Name </strong></span></p>\r\n</td>\r\n<td style=\"border-color: rgb(132, 63, 161);\" colspan=\"2\" valign=\"top\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\"><strong>Post</strong></span></p>\r\n</td>\r\n<td style