INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(96, 'Army Agniveer 2024 Apply Online', 'Join Indian Army has relased Online Common Entrance Exam CEE Agniveer in Agniveer Men / Women / Soldier Technical Nursing Assistant / Sepoy Pharma / JCO Religio', '<table style=\"border-collapse: collapse; width: 100%; border-spacing: 0px; border: 1px groove rgb(22, 145, 121); height: 2933.85px;\" border=\"1\" width=\"694\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr style=\"height: 231.583px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 231.583px;\" colspan=\"7\" valign=\"top\" width=\"694\">\r\n<h2 align=\"center\"><span style=\"color: rgb(255, 0, 255); font-size: 14pt;\"><strong>Join Indian Army (Bhartiya Sena) </strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(0, 128, 0); font-size: 14pt;\"><strong>Indian Army&nbsp;Common Entrance Exam CEE Exam 2024-2025 </strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(255, 0, 255); font-size: 14pt;\"><strong>Army Agniveer Rally Exam 2024 | Short Details of Notification</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(255, 0, 0); font-size: 14pt;\"><strong><a title=\"EXAM INFO BLOG\" href=\"../../\" target=\"_blank\" rel=\"noopener\">WWW.EXAMINFO.BLOG</a></strong></span><strong> </strong></h2>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 165.633px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 165.633px;\" colspan=\"4\" valign=\"top\" width=\"322\">\r\n<h2 align=\"center\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt;\"><strong>Important Dates</strong></span></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">Application Begin : <strong>13/02/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Last Date for Apply Online :<strong><span style=\"color: #ff0000;\"> 22/03/2024</span> </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Agniveer Exam Date : <strong>22/04/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">JCO Exam Date : <strong>22/04/2024 to 07/05/2024</strong></span></li>\r\n</ul>\r\n</td>\r\n<td style=\"border-color: rgb(22, 145, 121); height: 165.633px;\" colspan=\"3\" valign=\"top\" width=\"372\">\r\n<h2 align=\"center\"><span style=\"font-size: 12pt;\"><span style=\"color: #008000;\"><strong>Application Fee</strong></span><strong> </strong></span></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">General / OBC / EWS <strong>: 250/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">SC / ST :<strong> 250/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Pay the Examination Fee Through Debit Card / Credit Card / Net Banking.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 165.633px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 165.633px;\" colspan=\"7\" valign=\"top\" width=\"694\">\r\n<h2 align=\"center\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt;\"><strong>Army Agniveer Rally Recruitment :&nbsp; <span style=\"color: #ff00ff;\">Age Limit Details 2024 </span></strong></span></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\"><strong>For Agniveer GD / Technical / Assistant / Tradesman :</strong> 17.5 to 21 Years (01/10/2003 to 01/04/2007)<strong> </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>For Soldier Technical :</strong> 17.5 to 23 Years (01/10/2001 to 01/04/2007)</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>For Sepoy Pharma :</strong> 19-25 Years (01/10/1999 to 01/04/2005)</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>For JCO Religious Teacher :</strong> 27-34 Years as on 01/10/2024</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 72.8333px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 72.8333px;\" colspan=\"7\" valign=\"top\" width=\"694\">\r\n<h2 align=\"center\"><span style=\"color: rgb(255, 0, 255); font-size: 12pt;\"><strong>Army Agniveer Rally </strong><strong>Recruitment 2024 : <span style=\"color: #008000;\">Vacancy Details</span></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 50px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 50px;\" valign=\"top\" width=\"115\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\"><strong>Post Name</strong></span></p>\r\n</td>\r\n<td style=\"border-color: rgb(22, 145, 121); height: 50px;\" colspan=\"6\" valign=\"top\" width=\"579\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\"><strong>Army Agniveer Rally Eligibility 2024</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 243.2px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 243.2px;\" valign=\"top\" width=\"115\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\">Agniveer in General Duty GD, Technical, Assistant, Store Keeper, Tradesman <strong>(Men)</strong></span></p>\r\n</td>\r\n<td style=\"border-color: rgb(22, 145, 121); height: 243.2px;\" colspan=\"6\" valign=\"top\" width=\"579\">\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">Agniveer Army Recruitment Candidate must be a resident of the district from where the rally is going to apply for recruitment.</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>Education Qualification :</strong> Class 8th, 10th, 12th Post Wise Eligibility.</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>Physical Eligibility Group I:</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Height :</span></li>\r\n<li><span style=\"font-size: 12pt;\">For Agniveer Office Assistant / Store Keeper : <strong>162 CM&nbsp; </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">For All other Agniveer Post (GD, Technical / Tradesman) : <strong>169 CM</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">1.6 KM Running : <strong>5 Min 30 Second</strong> &ndash; 60 Marks</span></li>\r\n<li><span style=\"font-size: 12pt;\">Pull Ups : <strong>10 Times &ndash; </strong>40 Marks<strong> </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">9 Feet Ditch</span></li>\r\n<li><span style=\"font-size: 12pt;\">Zigzag Balance</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>More Details Read the Army Rally Notification. </strong></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 185.6px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 185.6px;\" valign=\"top\" width=\"115\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\">Agniveer in General Duty GD (Women Military Police)</span></p>\r\n<p align=\"center\"><span style=\"font-size: 12pt;\"><strong>(Women) </strong></span></p>\r\n</td>\r\n<td style=\"border-color: rgb(22, 145, 121); height: 185.6px;\" colspan=\"6\" valign=\"top\" width=\"579\">\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">Agniveer Army Recruitment Candidate must be a resident of the State from where the rally is going to apply for recruitment.</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>Education Qualification :</strong> Class 10th Matric Exam Passed with Minimum 45% Marks and 33% in Each Subjects.</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>Physical Eligibility Group I:</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>Height</strong> : 162 CMS</span></li>\r\n<li><span style=\"font-size: 12pt;\">1.6 KM Running : <strong>7 Min 30 Second</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">10 Feet Long Jump</span></li>\r\n<li><span style=\"font-size: 12pt;\">3 Feet High Jump</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>More Details Read the Army Rally Notification. </strong></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 280.4px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 280.4px;\" valign=\"top\" width=\"115\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\">Soldier Technical Nursing Assistant</span></p>\r\n</td>\r\n<td style=\"border-color: rgb(22, 145, 121); height: 280.4px;\" colspan=\"6\" valign=\"top\" width=\"579\">\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">Agniveer Army Recruitment Candidate must be a resident of the State from where the rally is going to apply for recruitment.</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>Education Qualification :</strong> 10+2 Intermediate with Science with Physics, Chemistry, Biology and English with minimum 50% Marks and 40% in Each Subject <strong>OR</strong> 10+2 Intermediate in Science Stream with Physics, Chemistry, Botany, Zoology and English with 50% Marks and 40% in Each Subjects.</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>Physical Eligibility:</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Height :</span></li>\r\n<li><span style=\"font-size: 12pt;\">For Eastern Uttar Pradesh : <strong>169 CM&nbsp; </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">For Western Uttar Pradesh : <strong>170 CM</strong>S</span></li>\r\n<li><span style=\"font-size: 12pt;\">Uttarakhand : <strong>163 CMS</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">1.6 KM Running : <strong>5 Min 45 Second</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Pull Ups :<strong> </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">9 Feet Ditch</span></li>\r\n<li><span style=\"font-size: 12pt;\">Zigzag Balance</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>More Details Read the Army Rally Notification. </strong></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 280.4px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 280.4px;\" valign=\"top\" width=\"115\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\">Sepoy Pharma</span></p>\r\n</td>\r\n<td style=\"border-color: rgb(22, 145, 121); height: 280.4px;\" colspan=\"6\" valign=\"top\" width=\"579\">\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">Agniveer Army Recruitment Candidate must be a resident of the State from where the rally is going to apply for recruitment.</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>Education Qualification :</strong> 10+2 Exam Passed and Qualified in D.Pharma with Minimum 55% Marks and Pharmacy Council Registration <strong>OR</strong> B.Pharma with 50% Marks and Registered in State Pharmacy Council .</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>Physical Eligibility:</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Height :</span></li>\r\n<li><span style=\"font-size: 12pt;\">For Eastern Uttar Pradesh : <strong>169 CM&nbsp; </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">For Western Uttar Pradesh : <strong>170 CM</strong>S</span></li>\r\n<li><span style=\"font-size: 12pt;\">Uttarakhand : <strong>163 CMS</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">1.6 KM Running : <strong>5 Min 45 Second</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Pull Ups :<strong> </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">9 Feet Ditch</span></li>\r\n<li><span style=\"font-size: 12pt;\">Zigzag Balance</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>More Details Read the Army Rally Notification. </strong></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 262.4px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 262.4px;\" valign=\"top\" width=\"115\">\r\n<p align=\"center\"><span style=\"font-size: 12pt;\">JCO Religious Teacher (Dharm Guru) Pandit, Pandit Gorkha, Granthi, Maulvi, Padre, Bodh Monk</span></p>\r\n<p align=\"center\">&nbsp;</p>\r\n</td>\r\n<td style=\"border-color: rgb(22, 145, 121); height: 262.4px;\" colspan=\"6\" valign=\"top\" width=\"579\">\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\"><strong>Education Qualification :</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>RT Pandit and Pandi Gorakha :</strong> Hindu Candidate with Shastri / Acharya in Sanskrit, (Karam Kand) as Main / Core Subject OR one Year Diploma in Karam Kand</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>RT Granthi :</strong> Sikh Candidate with Bachelor Degree in Any Stream, Gyani in Punjabi</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>RT Maulvi :</strong> Muslim Candidate : Bachelor Degree in Any Stream, &nbsp;Alim in Arabic or Adeeb-e-Mahir/ Urdu Mahir in Urdu</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>RT Padre :</strong> Christian Candidate with Bachelor Degree in Any Stream</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>RT Budhist :</strong> Budhist Candidate with Bachelor Degree in Any Stream</span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>Physical Eligibility Group I:</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Height :</span></li>\r\n<li><span style=\"font-size: 12pt;\">General : <strong>160 CM , </strong>Gorkhas &amp; Ladakhi Region<strong> : 157 CM </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Chest : 77 CM</span></li>\r\n<li><span style=\"font-size: 12pt;\">1.6 Km Running : <strong>8 Min </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\"><strong>More Details Read the Army Rally Notification. </strong></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 105.833px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 105.833px;\" colspan=\"7\" valign=\"top\" width=\"694\">\r\n<h2 align=\"center\"><span style=\"font-size: 12pt;\"><strong><span style=\"color: #008000;\">For ARO / ZRO&nbsp; / HQ Wise Vacancy Details Must Read the Army Common Entrance Exam CEE 2024 Notification.&nbsp;</span></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 105.833px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); height: 105.833px;\" colspan=\"7\" valign=\"top\" width=\"694\">\r\n<h2 align=\"center\"><span style=\"color: rgb(255, 0, 255); font-size: 12pt;\"><strong>Interested Candidate Can Read the Full Rally Notification Before Apply Indian Army Agniveer CEE 2024 Online Form.</strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 72.8333px;\">\r\n<td style=\"border-color: rgb(22, 145, 121); h