INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(142, 'UPSSSC Recruitment 2023 Eligibility Result 2024', 'Uttar Pradesh Subordinate Service Selection Commission (UPSSSC)has released the Junior Assistant, Junior Clerk and Assistant Grade III recruitment advertisement', '<table style=\"height: auto; border-collapse: collapse; width: 100%; border-spacing: 0px; margin-left: auto; margin-right: auto; border: 3px dashed rgb(248, 202, 198);\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"12\" valign=\"top\" width=\"783\">\r\n<h2 align=\"center\"><span style=\"color: rgb(185, 106, 217); font-size: 14pt; font-family: \'arial black\', sans-serif;\"><strong>Uttar Pradesh Subordinate Service Selection Commission (UPSSSC)</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(53, 152, 219); font-size: 14pt; font-family: \'arial black\', sans-serif;\"><strong>UPSSSC Junior Assistant, Clerk, Assistant Grade 3 Recruitment 2023 Mains Exam</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(241, 196, 15); font-size: 14pt; font-family: \'arial black\', sans-serif;\"><strong>UPSSSC Advt No. : 08-Exam/2023 Short Details of Notification</strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"7\" valign=\"top\" width=\"416\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: \'courier new\', courier, monospace; text-decoration: underline;\"><strong>Important Dates</strong></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Application Begin :<strong> 12/09/2023 </strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Last Date for Registration : <span style=\"color: #ff0000;\"><strong>03/10/2023</strong></span></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Fee Payment Last Date : <strong>03/10/2023</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Correction Last Date : <strong>10/10/2023</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Eligibility Result : <strong>14/03/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Exam Date : <strong>As per Schedule </strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Admit Card Available :<strong> Before Exam</strong></span></li>\r\n</ul>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"5\" valign=\"top\" width=\"367\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: \'courier new\', courier, monospace; text-decoration: underline;\"><strong>Application Fee</strong></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">General / OBC / EWS : <strong>25/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">SC / ST : <strong>25/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">PH (Dviyang) : <strong>25/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Pay the Examination Fee Through State Bank of India SBI I Collect Fee Mode or Pay the Exam Fee Through E Challan</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"12\" valign=\"top\" width=\"783\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: \'courier new\', courier, monospace; text-decoration: underline;\"><strong>UPSSSC Junior Assistant &amp; Other Post Notification 2023 : </strong><span style=\"color: red; text-decoration: underline;\"><strong>Age Limit as on 01/07/2023 </strong></span></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Minimum Age : <strong>18 Years</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Maximum Age : <strong>40 Years</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Age Relaxation Extra as per UPSSSC UP Junior Assistant, Junior Clerk &amp; Assistant Grade III Recruitment Advt No. 08/2023 Rules</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"12\" valign=\"top\" width=\"783\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: red; font-size: 12pt; font-family: \'courier new\', courier, monospace; text-decoration: underline;\"><strong>UPSSSC Junior Assistant, Clerk, AG III Recruitment 2023 : </strong><span style=\"color: rgb(0, 128, 0); text-decoration: underline;\"><strong>Vacancy Details Total : 5512 Post</strong></span></span></span></em></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"2\" valign=\"top\" width=\"226\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>Post Name</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"2\" valign=\"top\" width=\"130\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>Total Post </strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"8\" valign=\"top\" width=\"427\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>UPSSSC Junior Assistant, Clerk, AG III Eligibility</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center; border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"2\" valign=\"top\" width=\"226\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Junior Assistant / Junior Clerk / Assistant Grade III</span></td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"2\" valign=\"top\" width=\"130\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">5512</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"8\" valign=\"top\" width=\"427\">\r\n<ul>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">UPSSSC PET 2022 Score Card.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">10+2 Intermediate Exam in Any Recognized Board in India.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Hindi Typing 25 WPM and English Typing 30 WPM</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">NIELIT CCC Exam Passed</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">More Details Read the Notification.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"12\" valign=\"top\" width=\"783\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: \'courier new\', courier, monospace; text-decoration: underline;\"><strong>UPSSSC Advt No 08-Exam/2023 Various Post :&nbsp; </strong><span style=\"color: red; text-decoration: underline;\"><strong>Category Wise Vacancy Details</strong></span></span></span></em></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" valign=\"top\" width=\"166\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>Post Name</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"2\" valign=\"top\" width=\"141\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>General</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"5\" valign=\"top\" width=\"120\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>EWS</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" valign=\"top\" width=\"97\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>OBC</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" valign=\"top\" width=\"101\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>SC</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" valign=\"top\" width=\"73\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>ST</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" valign=\"top\" width=\"85\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>Total</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" valign=\"top\" width=\"166\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Junior Assistant / Junior Clerk / Assistant Grade III</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"2\" valign=\"top\" width=\"141\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">1889</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"5\" valign=\"top\" width=\"120\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">326</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" valign=\"top\" width=\"97\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">763</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" valign=\"top\" width=\"101\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">770</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" valign=\"top\" width=\"73\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">83</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" valign=\"top\" width=\"85\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">3831+1681</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"height: auto !important; border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"12\" valign=\"top\" width=\"783\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: red; font-size: 12pt; font-family: \'courier new\', courier, monospace; text-decoration: underline;\"><strong>How to Fill : UPSSSC Junior Assistant, Clerk, AG III Recruitment Online Form 2023</strong></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>There are 02 types to apply online for UPSSSC Junior Assistant, Junior Clerk and Assistant Grade III Recruitment Advt No. 08-Exam/2023 Recruitment 2023.</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>First:</strong> In this, the candidate will have to login with his personal information, the information that has to be given is: PET Registration Number, Date of Birth, Gender, Domicile and Category.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>Second :</strong> In this, the candidate will have to login through his OTP, the information that has to be given is: UPSSSC PET 2022 Registration Number and OTP Password.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">After login, the complete information of the candidate, his photo and signature will also be visible, the candidate will have to fill the information related to the post he is asking for and the application fee: Rs.25/- will have to be paid.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Kindly Check and Collect the All Document - Eligibility, ID Proof, Address Details, Basic Details.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Kindly Ready Scan Document Related to Recruitment Form - Photo, Sign, ID Proof, Etc.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Before Apply Online / Submit Application Form Must Check the Preview and All Column Carefully.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\">Take A Print Out of Final Submitted Form.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"12\" valign=\"top\" width=\"783\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: \'courier new\', courier, monospace; text-decoration: underline;\"><strong>Some Useful Important Links</strong></span></span></em></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"5\" valign=\"top\" width=\"370\">\r\n<h2 style=\"text-align: left; padding-left: 40px;\" align=\"center\"><span style=\"color: red; font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>Download Eligibility Result</strong></span></h2>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"7\" valign=\"top\" width=\"413\">\r\n<h2 align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong><a title=\"UPSSSC Various Post 2023 Online Result\" href=\"https://upsssc.gov.in/ResultsDire.aspx\" target=\"_blank\" rel=\"noopener\">Click Here</a></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"5\" valign=\"top\" width=\"370\">\r\n<h2 style=\"text-align: left; padding-left: 40px;\" align=\"center\"><span style=\"color: red; font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>How to Check Eligibility Result (Video Hindi)</strong></span></h2>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"7\" valign=\"top\" width=\"413\">\r\n<h2 align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong><a title=\"UPSSSC Various Post 2023 Online Result\" href=\"https://www.youtube.com/watch?v=CKumXCHWI9A\" target=\"_blank\" rel=\"noopener\">Click Here</a></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"5\" valign=\"top\" width=\"370\">\r\n<h2 style=\"text-align: left; padding-left: 40px;\" align=\"center\"><span style=\"color: red; font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>Download Eligibility Result Notice</strong></span></h2>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"7\" valign=\"top\" width=\"413\">\r\n<h2 align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong><a title=\"UPSSSC Various Post 2023 Online Result\" href=\"https://www.sarkariresults.org.in/wp-content/uploads/2024/03/upsssc-result-notice.pdf\" target=\"_blank\" rel=\"noopener\">Click Here</a></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"5\" valign=\"top\" width=\"370\">\r\n<h2 style=\"text-align: left; padding-left: 40px;\" align=\"center\"><span style=\"color: red; font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong>Apply Online</strong></span></h2>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"7\" valign=\"top\" width=\"413\">\r\n<h2 align=\"center\"><span style=\"font-size: 12pt; font-family: \'courier new\', courier, monospace;\"><strong><a title=\"UPSSSC Various Post 2023 Online Registration\" href=\"https://bit.ly/3pA3Wgj\" target=\"_blank\" rel=\"noopener\">Click Here</a></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(248, 202, 198);\" colspan=\"5\" valign=\"top\" width=\"370\">\r\n<h2 style=\"text-align: left; padding-left: 40px;\" align=\"center\"><span style=\"color: red; font-size: 12pt; font-fa