INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(143, 'UPSSSC ASO 072019 Supplementary Result 2024', 'Uttar Pradesh Subordinate Service Selection Commission (UPSSSC, Lucknow) Are Recently Uploaded Answer Key & Objection Link 2022 for the Statistical Officer Post', '<table style=\"border-collapse: collapse; width: 100%; border-spacing: 0px; margin-left: auto; margin-right: auto; border: 3px groove rgb(251, 238, 184);\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(251, 238, 184);\" colspan=\"12\" valign=\"top\" width=\"604\">\r\n<h2 align=\"center\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 14pt; color: rgb(185, 106, 217);\"><strong>Uttar Pradesh Subordinate Service Selection Commission (UPSSSC)</strong><strong> </strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(53, 152, 219); font-family: arial, helvetica, sans-serif; font-size: 14pt;\"><strong>Assistant Statistical Officer &amp; Research Officer Admit Card 2022</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(241, 196, 15); font-family: arial, helvetica, sans-serif; font-size: 14pt;\"><strong>Advt No. 07-Exam/2019 Short Details of Notification</strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(251, 238, 184);\" colspan=\"6\" valign=\"top\" width=\"305\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: georgia, palatino, serif; font-size: 12pt; text-decoration: underline;\"><strong>Important Dates</strong></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Application Begin <strong>: 19/09/2019</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Last Date for Apply Online <strong>: <span style=\"color: #ff0000;\">09/10/2019</span></strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Last Date Pay Exam Fee <strong>: 09/10/2019</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Re Upload Photo and Signature <strong>: 08/11/2020</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Exam Date <strong>: 22 May 2022 </strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Answer Key Available <strong>: 12-19 July 2022</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Revised Answer Key Available <strong>: 31/08/2022</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Result Available <strong>: 15/02/2023</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">DV Letter Available <strong>: 14/03/2024</strong></span></li>\r\n</ul>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(251, 238, 184);\" colspan=\"6\" valign=\"top\" width=\"299\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: georgia, palatino, serif; font-size: 12pt; text-decoration: underline;\"><strong>Application Fee</strong></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">General / OBC : <strong>185/-</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">SC / ST : <strong>95/-</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">PH (Divyang) <strong>: 25/-</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Pay the Exam Fee Through Debit Card / Credit Card / Net Banking Mode.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(251, 238, 184);\" colspan=\"6\" valign=\"top\" width=\"305\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: georgia, palatino, serif; font-size: 12pt; text-decoration: underline;\"><strong>Age Limit as on </strong><span style=\"color: red; text-decoration: underline;\"><strong>01/07/2019</strong></span></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Minimum Age <strong>: 21 Years</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Maximum Age <strong>: 40 Years</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Age Relaxation Extra as per Rules.<strong> </strong></span></li>\r\n</ul>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(251, 238, 184);\" colspan=\"6\" valign=\"top\" width=\"299\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: georgia, palatino, serif; font-size: 12pt; text-decoration: underline;\"><strong>Eligibility</strong></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Master Degree in Mathematics or Mathematical statistics or Commerce or Economics or statistic.</span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">One Year Diploma in Computer Science.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(251, 238, 184);\" colspan=\"12\" valign=\"top\" width=\"604\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: georgia, palatino, serif; font-size: 12pt; text-decoration: underline;\"><strong>Vacancy Details <span style=\"color: red; text-decoration: underline;\">Total Post : 904 Post</span></strong></span></span></em></h2>\r\n</td>\r\n<