INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(176, 'UPSC Civil Services Pre Exam Postponed', 'Union Public Service Commission (UPSC) Civil Services and Forest Service Examination 2024.', '<table style=\"border-collapse: collapse; width: 100%; border-spacing: 0px; margin-left: auto; margin-right: auto; border: 3px groove rgb(236, 202, 250);\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"7\" valign=\"top\" width=\"616\">\r\n<h2 align=\"center\"><span style=\"color: rgb(53, 152, 219); font-family: arial, helvetica, sans-serif; font-size: 14pt;\"><strong>Union Public Service Commission (UPSC)</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(241, 196, 15); font-family: arial, helvetica, sans-serif; font-size: 14pt;\"><strong>UPSC Civil Service / Forest Service IAS / IFS Recruitment 2024</strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"5\" valign=\"top\" width=\"309\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: \'book antiqua\', palatino, serif; font-size: 12pt; text-decoration: underline;\"><strong>Important Dates</strong></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Application Begin :<strong> 14/02/2024</strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Last Date for Apply Online : <strong><span style=\"color: #ff0000;\">06/03/2024</span> </strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Last Date Pay Exam Fee : <strong>06/03/2024</strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Correction Date : <strong>07-13 March 2024</strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Pre Exam Date : <strong>26/05/2024 (Postponed)</strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Admit Card Available : <strong>Before Exam</strong></span></li>\r\n</ul>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"307\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: \'book antiqua\', palatino, serif; font-size: 12pt; text-decoration: underline;\"><strong>Application Fee</strong></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">General / OBC / EWS :<strong> 100/-</strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">SC / ST / PH : <strong>0/- (Exempted)</strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">All Category Female :<strong> 0/- (Nil)</strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Pay the Examination Fee Through Debit Card, Credit, Card, Net Banking or E Challan Fee Mode Only</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"7\" valign=\"top\" width=\"616\">\r\n<h2 align=\"center\"><em><span style=\"color: rgb(0, 128, 0); font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><strong>UPSC IAS / IFS Pre Notification 2024 :&nbsp; <span style=\"color: red;\">Age Limit as on 01/08/2024</span></strong></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Minimum Age : <strong>21 Years</strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Maximum Age : <strong>32 Years</strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Age Relaxation Extra as per UPSC Civil Services and Forest Exam Exam 2024 Recruitment Rules</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"7\" valign=\"top\" width=\"616\">\r\n<h2 align=\"center\"><em><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><strong><span style=\"color: red;\">UPSC Civil Services / Forest Service <span style=\"color: #008000;\">Recruitment 2024&nbsp; : Vacancy Details Total : 1206 Post</span></span> </strong></span></em></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"139\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><strong>Post Name</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"106\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><strong>Total Post</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"371\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><strong>UPSC Civil Services Exam Eligibility</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"139\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Administrative Service IAS (Civil Services)</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"106\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">1056</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"371\">\r\n<ul>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Bachelor Degree in Any Stream in Any Recognized University in India</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"139\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Forest Service (IFS)</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"106\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">150</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"371\">\r\n<ul>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Bachelor Degree as one of Subject Animal Husbandry &amp; Veterinary Science, Botany, Chemistry, Geology, Mathematics, Physics, Statistics and Zoology, Agriculture or Equivalent.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"206\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Administrative Service.</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"189\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Foreign Service</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"221\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Police Service.</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"206\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian P &amp; T Accounts &amp; Finance Service, Gr A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"189\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Audit and Accounts Service, Group A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"221\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Defence Accounts Service, Group A</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"206\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Revenue Service (I.T.), Group A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"189\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Postal Service, Group A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"221\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Civil Accounts Service, Group A</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"206\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Railway Traffic Service, Group A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"189\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Pondicherry Civil Service, Group B</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"221\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Pondicherry Police Service, Group B</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"206\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Trade Service, Group A (Gr. III).</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"189\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Corporate Law Service, Group A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"221\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Information Service (Junior Grade), Gr A</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"206\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Defence Accounts Service, Group A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"189\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Revenue Service (I.T.), Group A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"221\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Railway Accounts Service, Group A</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"206\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Railway Personnel Service, Group A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"189\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Defence Estates Service, Group A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"221\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Assistant Security Commissioner in Railway Protection Force, Gr A</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"206\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Ordnance Factories Service, Group A</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"4\" valign=\"top\" width=\"189\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Indian Revenue Service (Customs and Central Excise)</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"221\">\r\n<p align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Armed Forces Headquarters Civil Service, Group B</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"7\" valign=\"top\" width=\"616\">\r\n<h2 align=\"center\"><em><span style=\"color: rgb(0, 128, 0); font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><strong>How to Fill IAS / IFS Pre Exam 2024 Online Form</strong></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">To apply for Civil Services and Forest Services Recruitment 2024 in UPSC, it will be mandatory for the candidate to do One Time Registration OTR.</span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Photo Instruction : The photo of the candidate should not be more than 10 days old and the name of the candidate and the date of taking the photo should also be written on the photo, the background of the photo should also be white.</span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">OBC certificate should be issued after 01 April 2023.</span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Union Public Service Commission UPSC Civil Services / Forest Service IAS / IFS Prelim Exam Latest Jobs Recruitment 2024. Candidate Can Apply Between <strong>14/02/2024 to 06/03/2024.</strong></span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Candidate Read the Notification Before Apply the Recruitment Application Form in UPSC 2024.</span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Kindly Check and Collect the All Document - Eligibility, ID Proof, Address Details, Basic Details.</span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Kindly Ready Scan Document Related to Recruitment Exam Form - Photo, Sign, ID Proof, Etc.</span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Before Submit the Application Form Must Check the Preview and All Column Carefully.</span></li>\r\n<li><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\">Take A Print Out of Final Submitted Form.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"7\" valign=\"top\" width=\"616\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: \'book antiqua\', palatino, serif; font-size: 12pt; text-decoration: underline;\"><strong>Some Useful Important Links</strong></span></span></em></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"5\" valign=\"top\" width=\"309\">\r\n<h2 align=\"center\"><span style=\"color: red; font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><strong>Download Pre Exam Postponed Notice </strong></span></h2>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"307\">\r\n<h2 align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><a title=\"UPSC IAS IFS Pre 2024 Online Form\" href=\"https://upsc.gov.in/sites/default/files/Ticker-CSP-2024-Postponement-engl-19032024.pdf\" target=\"_blank\" rel=\"noopener\"><strong>Click Here</strong></a></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"5\" valign=\"top\" width=\"309\">\r\n<h2 align=\"center\"><span style=\"color: red; font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><strong>Apply Correction / Edit Through OTR </strong></span></h2>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"307\">\r\n<h2 align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><a title=\"UPSC IAS IFS Pre 2024 Online Form\" href=\"https://upsconline.nic.in/upsc/OTRP/index.php\" target=\"_blank\" rel=\"noopener\"><strong>Click Here</strong></a></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"5\" valign=\"top\" width=\"309\">\r\n<h2 align=\"center\"><span style=\"color: red; font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><strong>Apply Online Through OTR </strong></span></h2>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"307\">\r\n<h2 align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><a title=\"UPSC IAS IFS Pre 2024 Online Form\" href=\"https://upsconline.nic.in/upsc/OTRP/index.php\" target=\"_blank\" rel=\"noopener\"><strong>Click Here</strong></a></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"5\" valign=\"top\" width=\"309\">\r\n<h2 align=\"center\"><span style=\"color: red; font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><strong>Download Notification</strong></span></h2>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"307\">\r\n<h2 align=\"center\"><span style=\"font-family: \'book antiqua\', palatino, serif; font-size: 12pt;\"><a title=\"UPSC IAS IFS Pre 2024 Notification \" href=\"https://upsc.gov.in/sites/default/files/Notif-CSP-24-engl-140224.pdf\" target=\"_blank\" rel=\"noopener\"><strong>Civil Services</strong></a> | <a title=\"UPSC IAS IFS Pre 2024 Notification \" href=\"https://upsc.gov.in/sites/default/files/Notif-IFSP-24-engl-140224.pdf\" target=\"_blank\" rel=\"noopener\"><strong>Forest Services</strong></a></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"5\" valign=\"top\" width=\"309\