INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(183, 'SSC Constable GD in BSF CISF Assam Rifles Recruitment 2023', 'Staff Selection Commission (SSC) has released the notification of Constable GD in BSF, CISF, ITBP, CRPF, NCB, SSF, Assam Rifles Examination 2023.', '<table style=\"width: 100%; border-collapse: collapse; border-spacing: 0px; border: 3px ridge rgb(236, 202, 250); margin-left: auto; margin-right: auto;\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr style=\"height: 14.091px;\">\r\n<td style=\"width: 99.8909%; border-color: rgb(236, 202, 250); height: 14.091px; border-width: 3px;\" colspan=\"21\" valign=\"top\" width=\"798\">\r\n<h2 align=\"center\"><span style=\"color: rgb(255, 12, 195); font-size: 14pt;\"><strong>Staff Selection Commission (SSC)</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(5, 0, 255); font-size: 14pt;\"><strong>SSC Constable GD in BSF, CISF, ITBP, CRPF, NCB, SSF, Assam Rifles Recruitment 2023</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(255, 12, 195); font-size: 14pt;\"><strong>SSC GD Constable Exam 2023 : Short Details of Notification</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"font-size: 14pt;\"><strong><a title=\"Exam Info Result Official Website\" href=\"../../\" target=\"_blank\" rel=\"noopener\">WWW.EXAMINFO.BLOG</a></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 234.727px;\">\r\n<td style=\"width: 55.1819%; border-color: rgb(236, 202, 250); height: 234.727px; border-width: 3px;\" colspan=\"11\" valign=\"top\" width=\"423\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(45, 194, 107); font-size: 12pt; text-decoration: underline;\"><strong>Important Dates</strong></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">Application Begin :&nbsp;<strong>24/11/2023</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Last Date for Apply Online :<strong>&nbsp;31/12/2023 upto 11 PM</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Pay Exam Fee Last Date :&nbsp;<strong>01/01/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Correction Date :&nbsp;<strong>04-06 January 2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Exam Date CBT :&nbsp;<strong>20 February to 12 March 2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Re Exam Date CBT :&nbsp;<strong>30 March 2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Admit Card Available :&nbsp;<strong>Before Exam</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Answer Key Available :&nbsp;<strong>After Exam</strong></span></li>\r\n</ul>\r\n</td>\r\n<td style=\"width: 44.709%; border-color: rgb(236, 202, 250); height: 234.727px; border-width: 3px;\" colspan=\"10\" valign=\"top\" width=\"376\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(45, 194, 107); font-size: 12pt; text-decoration: underline;\"><strong>Application Fee</strong></span></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">General / OBC / EWS :&nbsp;<strong>100/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">SC / ST :&nbsp;<strong>0/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">All Category Female :&nbsp;<strong>0/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Pay the Exam Fee Through Debit Card, Credit Card, Net Banking or E Challan</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 140.182px;\">\r\n<td style=\"width: 99.8909%; border-color: rgb(236, 202, 250); height: 140.182px; border-width: 3px;\" colspan=\"21\" valign=\"top\" width=\"798\">\r\n<h2 align=\"center\"><span style=\"text-decoration: underline;\"><span style=\"color: rgb(224, 62, 45); font-size: 12pt; text-decoration: underline;\"><strong>SSC GD Constable Recruitment 2023 :&nbsp;Age Limit as on</strong><strong>&nbsp;01/01/2024</strong></span></span></h2>\r\n<ul>\r\n<li><span style=\"font-size