INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(192, 'Haryana Police Constable Recruitment 2024', 'Haryana Staff Selection Commission, Haryana Police has relased Constable GD Male / Female Advt No. 01/2024 Recruitment Notification.', '<table style=\"border-collapse: collapse; width: 100%; border-spacing: 0px; margin-left: auto; margin-right: auto; border: 3px double rgb(194, 224, 244);\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"15\" valign=\"top\" width=\"793\">\r\n<h2 align=\"center\"><span style=\"color: rgb(185, 106, 217); font-family: \'arial black\', sans-serif; font-size: 14pt;\"><strong>Haryana Staff Selection Commission (HSSC)</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(241, 196, 15); font-family: \'arial black\', sans-serif; font-size: 14pt;\"><strong>Haryana Police HP Constable Recruitment 2024</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(53, 152, 219); font-family: \'arial black\', sans-serif; font-size: 14pt;\"><strong>HSSC Advt No. 01/2024 :&nbsp; Short Details of Notification</strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"9\" valign=\"top\" width=\"384\">\r\n<h2 align=\"center\"><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: helvetica, arial, sans-serif; font-size: 12pt; text-decoration: underline;\"><strong>Important Dates</strong></span></span></h2>\r\n<ul>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Application Begin <strong>: 20/02/2024 </strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Last Date for Apply Online <strong>: <span style=\"color: #ff0000;\">28/03/2024</span></strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Last Date Fee Payment <strong>: 58/03/2024</strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">CorrectionD ate <strong>: 22-28 March 2024</strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Exam Date <strong>: As per Schedule </strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Admit Card Available<strong> : Before Exam </strong></span></li>\r\n</ul>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"6\" valign=\"top\" width=\"409\">\r\n<h2 align=\"center\"><span style=\"text-decoration: underline;\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\"><strong><span style=\"color: rgb(0, 128, 0); text-decoration: underline;\">Application Fee</span></strong></span></span></h2>\r\n<ul>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Gen / Other State : <strong>0/-</strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Female General Haryana <strong>: 0/-</strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Reserve Category Male <strong>: 0/-</strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Reserve Category Female : <strong>0/-</strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">No Application Candidate Can Registered Online.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"15\" valign=\"top\" width=\"793\">\r\n<h2 align=\"center\"><em><span style=\"color: rgb(0, 128, 0); font-family: helvetica, arial, sans-serif; font-size: 12pt;\"><strong>Haryana Police Constable Notification 2024 : <span style=\"color: red;\">Age Limit as on</span><span style=\"color: red;\"> 01/02/2024</span></strong></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Minimum Age : <strong>18 Years</strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Maximum Age : <strong>25 Years</strong></span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Age Relaxation Extra as per<strong>&nbsp;</strong>Haryana Staff Selection Commission HSSC Police Constable Exam 2024 Rules</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"15\" valign=\"top\" width=\"793\">\r\n<h2 align=\"center\"><em><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\"><span style=\"color: #008000;\"><span style=\"color: red;\"><strong>Haryana Constable Recruitment 2024 :</strong></span></span> <span style=\"color: #008000;\">Vacancy Details <strong>Total 6000 Post</strong></span></span></em></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"3\" valign=\"top\" width=\"203\">\r\n<p align=\"center\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\"><strong>Post Name</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"4\" valign=\"top\" width=\"168\">\r\n<p align=\"center\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\"><strong>Total Post</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"8\" valign=\"top\" width=\"423\">\r\n<p align=\"center\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\"><strong>HSSC Haryana Police Constable Eligibility</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"3\" valign=\"top\" width=\"203\">\r\n<p align=\"center\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Constable Male GD</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"4\" valign=\"top\" width=\"168\">\r\n<p align=\"center\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">5000</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"8\" rowspan=\"3\" valign=\"top\" width=\"423\">\r\n<ul>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">HSSC CET Exam Qualified</span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">10+2 Intermediate Exam in Any Recognized Board in India.</span></li>\r\n<li><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Hindi / Sanskrit as a Subject in Matric Level.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"3\" valign=\"top\" width=\"203\">\r\n<p align=\"center\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">Constable Female GD</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"4\" valign=\"top\" width=\"168\">\r\n<p align=\"center\"><span style=\"font-family: helvetica, arial, sans-serif; font-size: 12pt;\">1000</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"3\" valign=\"top\" width=\"203\">&nbsp;</td>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"4\" valign=\"top\" width=\"168\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(194, 224, 244);\" colspan=\"15\" valign=\"top\" width=\"793\">\r\n<h2 align=\"center\"><em><span style=\"color: red; font-family: helvetica, arial, sans-serif; font-size: 12pt;\"><strong><span style=\"color: #008000;\">HSSC Constable Exam 2024 :