INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(243, 'IBPS PO 13th Recruitment 2023 Final Result', 'IBPS Probationary Officer / Management Trainee 13th Recruitment 2023 Final Result for XIII Exam', '<table style=\"border-collapse: collapse; width: 100%; border-spacing: 0px; margin-left: auto; margin-right: auto; border: 3px inset rgb(236, 202, 250);\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"13\" valign=\"top\" width=\"798\">\r\n<h2 align=\"center\"><span style=\"color: rgb(53, 152, 219); font-family: \'arial black\', sans-serif; font-size: 14pt;\"><strong>Institute Of Banking Personal Selection (IBPS)</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(241, 196, 15); font-family: \'arial black\', sans-serif; font-size: 14pt;\"><strong>IBPS Probationary Officer / Management Trainee XIII Recruitment 2023 Online Form </strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(185, 106, 217); font-family: \'arial black\', sans-serif; font-size: 14pt;\"><strong>IBPS CRP PO/MT XIII Exam 2023 : Short Details of Notification</strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"6\" valign=\"top\" width=\"458\">\r\n<h2 align=\"center\"><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: georgia, palatino, serif; font-size: 12pt; text-decoration: underline;\"><strong>Important Dates</strong></span></span></h2>\r\n<ul>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Application Begin<strong> : 01/08/2023</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Last Date for Apply Online<strong> : <span style=\"color: #ff0000;\">28/08/2023</span></strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Pay Exam Fee<strong> </strong>Last Date<strong> : 28/08/2023</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Pre Exam Date <strong>: September / October 2023 </strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Pre Exam Admit Card <strong>: 14/09/2023 </strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Pre Exam Result <strong>: 18/10/2023 </strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Mains Exam Date <strong>: November 2023 </strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Mains Exam Admit Card <strong>: 26/10/2023 </strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Mains Exam Result <strong>: 30/01/2024 </strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Mains Score Card Available <strong>: 02/02/2024 </strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Interview Letter Available <strong>: 12/02/2024 </strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Final Result <strong>: 01/04/2024 </strong></span></li>\r\n</ul>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"7\" valign=\"top\" width=\"340\">\r\n<h2 align=\"center\"><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: georgia, palatino, serif; font-size: 12pt; text-decoration: underline;\"><strong>Application Fee </strong></span></span></h2>\r\n<ul>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">General / OBC : <strong>850/-</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">SC / ST / PH : <strong>175/-</strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Pay the Examination Fee Through Online Fee Mode Debit Card, Credit Card, Net Banking, Mobile Banking, E Wallet, Cash Card, IMPS and E Challan Fee Mode</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"13\" valign=\"top\" width=\"798\">\r\n<h2 align=\"center\"><em><span style=\"color: rgb(0, 128, 0); font-family: georgia, palatino, serif; font-size: 12pt;\"><strong>IBPS PO 13 Recruitment 2023 : Vacancy Details </strong><strong><span style=\"color: red;\">Total 3049 Post </span> </strong></span></em></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"162\">\r\n<h3 align=\"center\"><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\"><strong>Post Name</strong></span></h3>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"105\">\r\n<h3 align=\"center\"><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\"><strong>Total Post</strong></span></h3>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"165\">\r\n<h3 align=\"center\"><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\"><strong>IBPS PO Age Limit</strong></span></h3>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"8\" valign=\"top\" width=\"367\">\r\n<h3 align=\"center\"><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\"><strong>IBPS PO Eligibility</strong></span></h3>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" valign=\"top\" width=\"162\">\r\n<p align=\"center\"><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Probationary Officer PO / Management Trainee MT XIII</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"105\">\r\n<p align=\"center\"><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">3049</span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"2\" valign=\"top\" width=\"165\">\r\n<p align=\"center\"><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">20-30 Years as on <strong>01/08/2023</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"8\" valign=\"top\" width=\"367\">\r\n<ul>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Bachelor Degree in Any Stream in Any Recognized Board in India.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"13\" valign=\"top\" width=\"798\">\r\n<h2 align=\"center\"><em><span style=\"color: red; font-family: georgia, palatino, serif; font-size: 12pt;\"><strong>IBPS PO 13 Notification 2023 : Bank Wise Vacancy Details </strong></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Bank of India BOI :&nbsp;224</span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Canara Bank :&nbsp;500</span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Central Bank of India :&nbsp;2000</span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Punjab National Bank PNB:&nbsp;200</span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Punjab &amp; Sind Bank:&nbsp;125</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style=\"height: auto !important;\">\r\n<td style=\"height: auto !important; border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"13\" valign=\"top\" width=\"798\">\r\n<h2 align=\"center\"><em><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\"><strong><span style=\"color: #008000;\">How to Fill IBPS PO XIII Recruitment 2023 Online Form</span> </strong></span></em></h2>\r\n<ul>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Institute of Banking and Personal Selection <span style=\"color: #000000;\"><span style=\"color: #000000;\">IBPS </span></span>Are Issued Notification and Invited Online Application Form for the PO / MT CRP XIII Recruitment 2023 Candidate Can Apply Online for <strong>01 August 2023 to 28 August 2023.</strong><strong> </strong></span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Candidate Read the Notification Before Apply the IBPS Bank Recruitment Application Form in IBPS Latest PO / MT Vacancies 2023.</span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Kindly Check and Collect the All Document - Eligibility, ID Proof, Address Details, Basic Details.</span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Kindly Ready Scan Document Related to Recruitment Form - Photo, Sign, ID Proof, Etc.</span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Before Submit the Application Form Must Check the Preview and All Column Carefully.</span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">If Candidate Required to Paying the Application Fee Must Submit. If You have Not the Required Application Fees Your Form is Not Completed.</span></li>\r\n<li><span style=\"font-family: georgia, palatino, serif; font-size: 12pt;\">Take A Print Out of Final Submitted Form.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250);\" colspan=\"13\" valign=\"top\" width=\"798\">\r\n<h2 align=\"center\"><em><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-family: georgia, palatin