INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(340, 'Indian Army Common Entrance Exam Exam 2024 Admit Card Out', 'Indian Army  CEE Exam 2024 (Agniveer Men / Women / Soldier Technical Nursing Assistant / Sepoy Pharma / JCO Religious Teacher Dharm Guru) Admit Card', '<table style=\"border-collapse: collapse; width: 100%; border-spacing: 0px; margin-left: auto; margin-right: auto; border: 2px solid rgb(194, 224, 244);\" border=\"1\" width=\"694\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border-width: 2px; border-color: rgb(194, 224, 244); width: 196.143%;\" colspan=\"7\" valign=\"top\" width=\"694\">\r\n<h2 align=\"center\"><span style=\"color: rgb(185, 106, 217); font-size: 14pt; font-family: \'arial black\', sans-serif;\"><strong>Join Indian Army (Bhartiya Sena) </strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(241, 196, 15); font-size: 14pt; font-family: \'arial black\', sans-serif;\"><strong>Indian Army&nbsp;Common Entrance Exam CEE Exam 2024-2025 </strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(53, 152, 219); font-size: 14pt; font-family: \'arial black\', sans-serif;\"><strong>Army Agniveer Rally Exam 2024 | Short Details of Notification</strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 2px; border-color: rgb(194, 224, 244); width: 55.8797%;\" colspan=\"4\" valign=\"top\" width=\"322\">\r\n<h2 align=\"center\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>Important Dates</strong></span></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\">Application Begin : <strong>13/02/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\">Last Date for Apply Online :<strong><span style=\"color: #ff0000;\"> 22/03/2024</span> </strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\">Agniveer Exam Date : <strong>22/04/2024 to 03/05/2024</strong></span></li>\r\n</ul>\r\n</td>\r\n<td style=\"border-width: 2px; border-color: rgb(194, 224, 244); width: 140.264%;\" colspan=\"3\" valign=\"top\" width=\"372\">\r\n<h2 align=\"center\"><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><span style=\"color: #008000;\"><strong>Application Fee</strong></span><strong> </strong></span></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\">General / OBC / EWS <strong>: 250/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\">SC / ST :<strong> 250/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\">Pay the Examination Fee Through Debit Card / Credit Card / Net Banking.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 2px; border-color: rgb(194, 224, 244); width: 196.143%;\" colspan=\"7\" valign=\"top\" width=\"694\">\r\n<h2 align=\"center\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>Army Agniveer Rally Recruitment :&nbsp; <span style=\"color: red;\">Age Limit Details 2024 </span></strong></span></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>For Agniveer GD / Technical / Assistant / Tradesman :</strong> 17.5 to 21 Years (01/10/2003 to 01/04/2007)<strong> </strong></span></li>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>For Soldier Technical :</strong> 17.5 to 23 Years (01/10/2001 to 01/04/2007)</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>For Sepoy Pharma :</strong> 19-25 Years (01/10/1999 to 01/04/2005)</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>For JCO Religious Teacher :</strong> 27-34 Years as on 01/10/2024</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 2px; border-color: rgb(194, 224, 244); width: 196.143%;\" colspan=\"7\" valign=\"top\" width=\"694\">\r\n<h2 align=\"center\"><span style=\"color: red; font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>Army Agniveer Rally </strong><strong>Recruitment 2024 : <span style=\"color: #008000;\">Vacancy Details</span></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 2px; border-color: rgb(194, 224, 244); width: 12.316%;\" valign=\"top\" width=\"115\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>Post Name</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 2px; border-color: rgb(194, 224, 244); width: 183.827%;\" colspan=\"6\" valign=\"top\" width=\"579\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>Army Agniveer Rally Eligibility 2024</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 2px; border-color: rgb(194, 224, 244); width: 12.316%;\" valign=\"top\" width=\"115\">\r\n<p align=\"center\"><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\">Agniveer in General Duty GD, Technical, Assistant, Store Keeper, Tradesman <strong>(Men)</strong></span></p>\r\n</td>\r\n<td style=\"border-width: 2px; border-color: rgb(194, 224, 244); width: 183.827%;\" colspan=\"6\" valign=\"top\" width=\"579\">\r\n<ul>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\">Agniveer Army Recruitment Candidate must be a resident of the district from where the rally is going to apply for recruitment.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>Education Qualification :</strong> Class 8th, 10th, 12th Post Wise Eligibility.</span></li>\r\n<li><span style=\"font-size: 12pt; font-family: helvetica, arial, sans-serif;\"><strong>Physica