INSERT INTO `post` (`post_id`, `title`, `sort_details`, `description`, `post_img`, `category`, `author`, `postStatus`, `post_date`, `last_update`, `remarks`, `post_keywords`) VALUES
(341, 'NTA National Common Entrance Test NCET 2024', 'National Testing Agency (NTA) has relased National Common Entrance Test NCET Admissions Notification.', '<table style=\"border-collapse: collapse; width: 100%; border-spacing: 0px; margin-left: auto; margin-right: auto; border: 3px solid rgb(236, 202, 250);\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250); width: 99.9127%;\" colspan=\"4\" valign=\"top\" width=\"753\">\r\n<h2 align=\"center\"><span style=\"color: rgb(185, 106, 217); font-size: 14pt;\"><strong>National Testing Agency (NTA)</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(53, 152, 219); font-size: 14pt;\"><strong>NTA National Common Entrance Test NCET 2024</strong></span></h2>\r\n<h2 align=\"center\"><span style=\"color: rgb(241, 196, 15); font-size: 14pt;\"><strong>NTA NCET Exam 2024 :&nbsp; Short Details of Notification</strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250); width: 56.4169%;\" colspan=\"3\" valign=\"top\" width=\"340\">\r\n<h2 align=\"center\"><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; text-decoration: underline;\"><strong>Important Dates</strong></span></span></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">Application Begin : <strong>13/04/2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Last Date for Apply Online :<span style=\"color: #ff0000;\"><strong> 30/04/2024 </strong></span></span></li>\r\n<li><span style=\"font-size: 12pt;\">Last Date Online Payment : <strong>30/04/2024 </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Correction Date : <strong>02-04 May 2024</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Exam Date : <strong>12 June 2024</strong><strong> </strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Admit Card Available : <strong>Before Exam</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">Result Declared :<strong> Notified Soon</strong></span></li>\r\n</ul>\r\n</td>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250); width: 43.4958%;\" valign=\"top\" width=\"414\">\r\n<h2 align=\"center\"><span style=\"text-decoration: underline;\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt; text-decoration: underline;\"><strong>Application Fee </strong></span></span></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">General : <strong>1200</strong>/-</span></li>\r\n<li><span style=\"font-size: 12pt;\">EWS / OBC : <strong>1000/-</strong></span></li>\r\n<li><span style=\"font-size: 12pt;\">SC / ST / PH : <strong>650</strong>/-</span></li>\r\n<li><span style=\"font-size: 12pt;\">Pay the Examination Fee Through E Challan Offline Mode or Pay the Exam Fee Through Online Debit Card, Credit Card or Net Banking Fee Mode</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250); width: 99.9127%;\" colspan=\"4\" valign=\"top\" width=\"753\">\r\n<h2 align=\"center\"><span style=\"font-size: 12pt;\"><strong><span style=\"color: #008000;\">National Common Entrance Test <span style=\"color: red;\">NCET Notification 2024 : Age Limit</span></span> </strong></span></h2>\r\n<ul>\r\n<li><span style=\"font-size: 12pt;\">No Age Limit in National Common Entrance Test NCET 2024</span></li>\r\n<li><span style=\"font-size: 12pt;\">For More Information Read the Information Brochure.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(236, 202, 250); width: 99.9127%;\" colspan=\"4\" valign=\"top\" width=\"753\">\r\n<h2 align=\"center\"><span style=\"color: rgb(0, 128, 0); font-size: 12pt;\"><strong>NTA National Common Entrance Test NCET Exam 2024 : <span style=\"color: red;\">Admission Details</span></strong></span></h2>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 3px; border-color: rgb(23